BADNAME = {'الشاعر', 'شاعر', 'الراجز', 'بعضهم', 'غيره', 'بعض', 'أحد', 'رجل', 'امرأة', 'المصنف', 'أبي', 'الله', 'النحويين', 'سيبويه', 'الكتاب', 'هذا', 'هذه', 'ذلك', 'مجهول', 'أحدهم', 'الأعشى'}      # «الأعشى» alone is ambiguous: kept only with a qualifier (see below)
HONOR = re.compile(r'\s+(?:رضي|رحمه|رحمهما|عليه|صلى|الجاهلي|الإسلامي|المخضرم|الصحابي|الراجز|الأموي|العباسي|الشاعر|الفارس|المشهور|المعروف|الأعور|الأسدي الجاهلي).*$')
def _name(tokens):
    out = []
    for t0 in tokens:
        t = t0.strip('،,.:;()«»"')
        if not t or t in STOPN: break
        out.append(t)
        if len(out) >= 6 or t0.endswith(('،', ',', '.', ':', ';')): break
    if not out: return ''
    n = ' '.join(out); n = HONOR.sub('', n).strip()
    n = re.sub(r'^(?:ل|لـ)(?=ال)', '', n)
    if len(n) < 3 or n in BADNAME or re.search(r'[0-9]', n): return ''
    if any(w in ('البيت', 'القصيدة', 'الأبيات', 'الرجز', 'قصيدة', 'الكتاب') for w in n.split()): return ''
    return n
P1 = re.compile(r'(?:^|[\s،:])(?:و?هو|و?هذا|و?هذه|و?هذان|و?هذين|و?هما|و?البيت|و?الأبيات|و?الرجز)\s+(?:من\s+)?(?:أبيات|بيتين|قصيدة|قصيدته|رجز|أرجوزة|مقطوعة|كلمة|قصيدة طويلة|أبيات ثلاثة|أبيات لـ?|قصيدة له|أبيات له)?\s*(?:ل|لـ)(?!م\b)(\S+(?:\s+\S+){0,6})')
P2 = re.compile(r'(?:قائله|قائلها|قائلهما|ينسب\s+(?:هذا\s+)?(?:البيت\s+)?إلى|لقائله|والقائل|وقائله|وقائلها)\s*:?\s*(?:هو\s+)?(\S+(?:\s+\S+){0,6})')
P3 = re.compile(r'^(?:و?قال|و?أنشد|و?قول|و?وقال)\s+(.+?)\s*:\s*$')
P4 = re.compile(r'(?:^|[\s،:])(?:و?هو|و?هي|و?البيت|و?الأبيات|و?البيتان)\s+(?:من\s+(?:أبيات|قصيدة|معلقة|مطلع قصيدة)\s+)?(?:ل|لـ)(?!م\b)(\S+(?:\s+\S+){0,6})')
P5 = re.compile(r'(?<!في )(?<!من )(?<!على )(?<!إلى )(?<!عن )(?:^|\s)(?:و?ترجمة|و?تقدمت ترجمة|و?تقدم ترجمة|و?قد تقدمت ترجمة|و?قد تقدمت ترجمته|و?قد مرت ترجمة|و?ستأتي ترجمة)\s+(?:ل|لـ)?(\S+(?:\s+\S+){0,5})')        # «وترجمة النابغة الذبياني قد تقدمت»: the book gives the biography of the poet of the shahid
P7 = re.compile(r'(?:و?نسبه|و?ينسب|و?عزاه|و?نسبها|و?نسبهما|و?يروى|و?روي)\s+(?:هذا\s+(?:البيت|الشعر)\s+)?(?:إلى\s+|ل|لـ)(\S+(?:\s+\S+){0,5})')
def poet_of(ctx):
    """the poet named by the books around the verse: the most frequent name among the quotations; '' when no book says"""
    names = []
    for c in ctx:
        cand = []
        if c['before']:
            m = P3.match(c['before'])
            if m: cand.append(_name(m.group(1).split()))
        for t in c['after'][:3]:
            for rx in (P2, P1):
                m = rx.search(t)
                if m: cand.append(_name(m.group(1).split()))
        names += [x for x in cand if x]
    if not names: return ''
    import collections
    return collections.Counter(names).most_common(1)[0][0]
CUES = [('يمدح', 'مدح'), ('مدح', 'مدح'), ('يهجو', 'هجاء'), ('هجا', 'هجاء'), ('يرثي', 'رثاء'), ('رثى', 'رثاء'), ('يخاطب', 'مخاطبة'), ('خاطب', 'مخاطبة'), ('يعتذر', 'الاعتذار إلى'), ('يعاتب', 'عتاب'), ('يتغزل', 'التغزل'), ('يشكو', 'الشكوى'), ('يتوعد', 'الوعيد'), ('يحرض', 'التحريض'), ('يخاطبها', 'مخاطبة'), ('يخاطبه', 'مخاطبة'), ('يصف', 'وصف'), ('وصف', 'وصف'), ('يفتخر', ''), ('يفخر', '')]
NOUN_FIRST = {'يفتخر': 'الفخر', 'يفخر': 'الفخر'}
OBJ_STOP = {'أولها', 'بقصيدة', 'لأجل', 'وتتصل', 'أوردها', 'وأنشده', 'وأنشدها', 'مما', 'وأبيات', 'ومنها', 'وزعم', 'حتى', 'وتقدم', 'لقيه', 'والصواب', 'وهجا', 'ويقول', 'ويعتذر', 'وأراد', 'ويعاتبه', 'وحض', 'ويمدح', 'لكنه', 'ويخص', 'وتقول', 'جعل', 'مطلعها', 'فسهر', 'وقومه', 'والله', 'وغيره', 'وفي', 'في', 'ونقل', 'وذكر', 'وروى', 'ووقع', 'ومثله','وبعده', 'وقبله', 'وأوله', 'وأولها', 'ثم', 'وقد', 'وكان', 'وهو', 'وهي', 'من', 'أنه', 'بأنه', 'وبعدها', 'فقال', 'فيقول', 'يقول', 'وقال', 'وقوله', 'إذ', 'حين', 'لما', 'لأن', 'ويروى', 'وفيه', 'وهذا', 'قال', 'ويقال', 'وروي', 'والذي', 'الذي', 'التي', 'وأنشد', 'حيث', 'وذلك', 'وإنما', 'وهما', 'فيها', 'فيه', 'وأولهما', 'وفي'}
EVENT_FIRST = {'غزوة', 'يوم', 'حرب', 'وقعة', 'معركة', 'رثاء', 'أخيه', 'ابنه', 'أبيه', 'امرأته', 'زوجته', 'ابنته', 'أمه', 'عبد', 'قتل', 'فتح'}      # «قاله في غزوة مؤتة»: only an event or a person, never «في الصحاح» / «في موضع آخر»
NAMES = set()                                                                        # filled by the builder with the poets' names found in the books
def occasion_of(ctx):
    """«يقال عند … / في …»: the occasion as the books word it. Only the strong cues: «يمدح/يهجو/يرثي/يخاطب/يعاتب/يعتذر إلى X», «يفتخر», and «قالها لما/حين …»"""
    for c in ctx:
        for t in claim_window(c):
            m0 = re.search(r'(?:قاله|قالها|قالهما)\s+في\s+(\S+(?:\s+\S+){1,6})', t)
            if m0:
                tail = _trim(m0.group(1).split())
                if tail and not re.search(r'[؟?]|آخره|مدح|هجاء|وصف', tail) and len(tail.split()) >= 2 and tail.split()[0] in EVENT_FIRST: return f'في {tail}'
            m = re.search(r'(?:قاله|قالها|قالهما|قال هذا|قال ذلك|أنشدها|أنشده)\s+(?:الشاعر\s+)?(لما|حين|عندما|حينما)\s+(\S+(?:\s+\S+){0,8})', t)
            if m:
                tail = _trim(m.group(2).split())
                if tail and len(tail.split()) >= 2 and not re.search(r'[؟?]|آخره|الى آخر|إلى آخر', tail): return f'عندما {tail}'
            for cue, noun in CUES:
                if noun in ('وصف', 'التغزل', 'الشكوى', 'الوعيد', 'التحريض', 'مخاطبة') and cue not in ('يخاطب', 'خاطب'): continue
                m = re.search(r'(?:^|[\s،:])' + cue + r'(?=\s|$)(?:\s+(?:بها|بهذا|بهما|به|لها|له))?(?:\s+(\S+(?:\s+\S+){0,5}))?', t)
                if not m: continue
                if cue in NOUN_FIRST:                                                 # «يفتخر بقومه…» opening the sentence that explains the verse, or «من قصيدة … يفتخر»; not «مما يفتخرون به»
                    if re.match(r'^و?\s*' + cue + r'\b', t) or re.search(r'(?:البيت|الأبيات|البيتان|قصيدة|أبيات|الرجز)[^.]{0,70}(?:^|[\s،:])' + cue + r'(?=\s|$)', t): return f'في {NOUN_FIRST[cue]}'
                    continue
                if re.match(r'(?:بهذا|بذلك|بهذه)\b', (m.group(1) or '').strip()) or re.search(r'\b(?:بهذا|بذلك)\b', ' '.join((m.group(1) or '').split()[:3])): continue      # «مدح أبو زبيد بهذا الشعر الوليد»: the object is the other way round
                obj = _trim((m.group(1) or '').split())
                if re.search(r'(?:^|\s)(?:أن|لكريم|مثل|الذي|هذا|لجوده)(?:\s|$)', obj): continue
                if not obj or re.search(r'[؟?]|آخره|الى آخر|إلى آخر', obj) or obj.split()[0].startswith('و'): continue
                if not (re.search(r'\b(?:بن|ابن|أبي|أبو|ذي|ذو)\b', obj) or obj in NAMES): continue      # only a named person: «عند مدح عمر بن عبد العزيز», not «عند مخاطبة الواحد…»
                return f'عند {noun} {obj}'
    return ''
def _trim(ws):
    out = []
    for w in ws:
        w2 = w.strip('،,.:;()«»"')
        if not w2 or w2 in OBJ_STOP or w.endswith('،') and out and len(out) >= 1: 
            if w2 and w2 not in OBJ_STOP and out is not None: out.append(w2)
            break
        out.append(w2)
        if w.endswith(('.', ':', '؛')): break
    if out and len(out[0]) >= 4 and out[0].endswith('ا') and out[0] not in ('أبا', 'أخا', 'حتى', 'إذا', 'عليا', 'ملكا') and len(out) == 1: out[0] = out[0][:-1]   # «جريرا» → «جرير» (accusative alif of a lone name)
    r = re.sub(r'\s*[-–—].*$', '', ' '.join(out[:7])); r = re.sub(r'\s+(?:رضي|رحمه|عليه|صلى)\b.*$', '', r).strip()
    r = re.sub(r'[؛;,.،:]+$', '', r).strip()
    r = re.sub(r'\s+(?:ومنها|والله أعلم|أحد|بني|ابن|بن|أبي|في|من|على|ثم|الذي|التي|وقد|أي|يعني)$', '', r).strip()
    r = re.sub(r'\s+(?:ومنها|والله أعلم|أحد|بني|ابن|بن|أبي)$', '', r).strip()
    return r

